// n8n's Gmail Trigger (simple: false) gives a parsed email: text, html,
// subject, from / to / cc .value[], id (Gmail's id), threadId, messageId
// (the email's own Message-ID, used to thread our reply) and headers.
// 0035: every recipient is checked against the agency's mailbox (not just
// the first "To"), automatic emails are skipped (no-reply senders,
// newsletters, out-of-office), and only the new part of a reply goes to
// Elliot -- not the whole quoted conversation underneath.
const msg = $json;
// 0046: an email with only attachments is still answered.
let attachmentCount = 0;
try { attachmentCount = Object.keys($input.first().binary || {}).filter((k) => /^attachment_\d+$/.test(k)).length; } catch (e) { attachmentCount = 0; }
const addrs = (f) => ((f && f.value) || []).map((v) => String(v.address || '').trim().toLowerCase()).filter(Boolean);
const fromEmail = addrs(msg.from)[0] || '';
const fromName = String((msg.from && msg.from.value && msg.from.value[0] && msg.from.value[0].name) || '').trim();
const recipients = [...new Set([...addrs(msg.to), ...addrs(msg.cc), ...addrs(msg.bcc)])];

function header(name) {
  const h = msg.headers;
  let v = '';
  try {
    if (h && typeof h.get === 'function') v = h.get(name);
    else if (h) v = h[name] ?? h[name.toLowerCase()];
  } catch (e) { v = ''; }
  if (!v && Array.isArray(msg.headerLines)) {
    const line = msg.headerLines.find((l) => String(l.key || '').toLowerCase() === name.toLowerCase());
    if (line) v = String(line.line || '').replace(/^[^:]*:\s*/, '');
  }
  if (v == null) return '';
  return typeof v === 'object' ? (v.value || v.text || JSON.stringify(v)) : String(v);
}

let text = String(msg.text || '');
if (!text.trim() && msg.html) {
  text = String(msg.html)
    .replace(/<(br|\/p|\/div|\/li|\/tr)\b[^>]*>/gi, '\n')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/[ \t]+/g, ' ');
}
text = text.replace(/\r\n/g, '\n');
// Only the new part of a reply: cut at "On ... wrote:" / "W dniu ... pisze:" /
// "-----Original Message-----", and drop quoted lines.
const cut = text.search(/\n[ \t]*(On\s[^\n]{0,200}(\n[^\n]{0,200})?\swrote:|W dniu\s[^\n]{0,200}(\n[^\n]{0,200})?\s(pisze|napisał\(a\)|napisała|napisał):|-{2,}\s*(Original Message|Wiadomość oryginalna|Forwarded message))/i);
if (cut > 0) text = text.slice(0, cut);
const body = text.split('\n').filter((l) => !/^\s*>/.test(l)).join('\n').replace(/\n{3,}/g, '\n\n').trim().slice(0, 4000);
const subject = String(msg.subject || '').trim();

const autoSubmitted = header('auto-submitted').toLowerCase();
const precedence = header('precedence').toLowerCase();
let skip = null;
if (!fromEmail) skip = 'no_sender';
else if (/^(no-?reply|do-?not-?reply|mailer-daemon|postmaster|bounce)/i.test(fromEmail.split('@')[0])) skip = 'automatic_sender';
else if (autoSubmitted && autoSubmitted !== 'no') skip = 'auto_submitted';
else if (/bulk|list|junk/.test(precedence) || header('list-unsubscribe') || header('list-id')) skip = 'mailing_list';
else if (!body && !subject && !attachmentCount) skip = 'empty';

const rfcId = String(msg.messageId || '').trim();
return [{
  json: {
    skip: !!skip,
    reason: skip,
    gmail_message_id: msg.id || '',
    gmail_thread_id: msg.threadId || msg.id || '',
    rfc_message_id: /^<.+>$/.test(rfcId) ? rfcId : (rfcId ? `<${rfcId}>` : ''),
    from_email: fromEmail,
    from_name: fromName,
    to_email: recipients[0] || '',
    recipients,
    subject,
    body,
    // What Elliot reads: the subject is often the whole question.
    message: subject && !/^(re|odp|fw|fwd|pd)\s*:/i.test(subject) ? `Subject: ${subject}\n\n${body || subject}` : (body || subject || '(No text: the client sent attachments only.)')
  }
}];

// Hands the email to Elliot (workflow 01, the same agent as WhatsApp and the
// website chat): answers from the knowledge base, listings with links,
// viewings booked with a confirmation email, hand-over to the team.
// Elliot's address: worked out from this n8n's own address, or pasted below.
const ELLIOT_CHAT_WEBHOOK_URL = 'PASTE_ELLIOT_CHAT_WEBHOOK_URL_HERE';

function setting(name, pasted) {
  try { if ($vars && $vars[name]) return String($vars[name]); } catch (e) {}
  try { if ($env && $env[name]) return String($env[name]); } catch (e) {}
  return String(pasted || '').startsWith('PASTE_') ? '' : String(pasted || '');
}

const f = $('Extract Email Fields').first().json;
const tenant = $('Lookup Tenant by Mailbox').first().json;
const contact = $('Upsert Contact').first().json || {};
const conversationId = $('Get or Create Conversation (Email)').first().json.id;
// 0046: the files the client attached (links only for the ones Elliot reads).
let files = [];
try { files = $('Collect Attachments').first().json.files || []; } catch (e) { files = []; }

let url = setting('ELLIOT_CHAT_WEBHOOK_URL', ELLIOT_CHAT_WEBHOOK_URL);
if (!url) {
  let resume = '';
  try { resume = String($execution.resumeUrl || ''); } catch (e) {}
  const at = resume.indexOf('/webhook-waiting/');
  if (at > 0) url = resume.slice(0, at) + '/webhook/chat';
}
if (!url) {
  throw new Error("Can't work out Elliot's address: paste the chat webhook URL (workflow 01's Production URL) into ELLIOT_CHAT_WEBHOOK_URL in this node.");
}

// 0047: Elliot's own workflows use the secret-protected address, which is the
// only one allowed to say "this is email / WhatsApp from this client".
url = String(url || '').replace(/\/chat\/?(\?.*)?$/, '/chat-internal');

return [{ json: {
  chat_url: url,
  request: {
    tenant_slug: tenant.tenant_slug,
    message: f.message,
    conversation_id: conversationId,
    channel: 'email',
    contact: { name: contact.name || f.from_name || null, email: f.from_email },
    attachments: files
  }
} }];

// What Elliot (workflow 01) answered: { reply }, or { human: true } when a
// team member has taken the conversation over (then nothing is sent; they
// reply from the dashboard). If Elliot failed, the client still gets a short
// holding reply and the failure is logged.
const FALLBACK = "Thank you for your message. Someone from our team will get back to you shortly.";
const r = $input.first().json;
const status = Number(r.statusCode || 0);
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* not JSON */ } }
const req = $('Build Elliot Request').first().json.request;
const base = { conversation_id: req.conversation_id };
if (!(status >= 200 && status < 300) || !body || typeof body !== 'object') {
  return [{ json: { ...base, reply: FALLBACK, human: false, elliot_error: `Elliot answered with HTTP ${status || 'no response'}` } }];
}
if (body.human === true) return [{ json: { ...base, reply: '', human: true, elliot_error: null } }];
const reply = String(body.reply || '').trim();
return [{ json: { ...base, reply: reply || FALLBACK, human: false, elliot_error: reply ? null : 'Elliot returned an empty reply' } }];

// Elliot's answer as a reply in the same Gmail thread: "Re:" subject,
// In-Reply-To / References set to the client's Message-ID, plain text
// (Elliot's Markdown turned into clean text), UTF-8 throughout.
function toPlain(text) {
  let t = String(text || '').replace(/\r\n/g, '\n');
  t = t.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, (m, label, url) => (label.trim() === url ? url : `${label.trim()}: ${url}`));
  t = t.replace(/\*\*(.+?)\*\*/g, '$1').replace(/__(.+?)__/g, '$1');
  t = t.replace(/^#{1,6}\s+/gm, '');
  t = t.replace(/^(\s*)\*\s+/gm, '$1- ');
  return t.replace(/\n{3,}/g, '\n\n').trim();
}
const b64 = (s) => Buffer.from(String(s), 'utf8').toString('base64');
const f = $('Extract Email Fields').first().json;
const tenant = $('Lookup Tenant by Mailbox').first().json;
const answer = $('Read Elliot Answer').first().json;
const base = f.subject || 'Your enquiry';
const subject = /^(re|odp)\s*:/i.test(base) ? base : `Re: ${base}`;
const text = toPlain(answer.reply) + '\n';
const headers = [
  `To: ${f.from_email}`,
  `Subject: =?UTF-8?B?${b64(subject)}?=`,
  f.rfc_message_id ? `In-Reply-To: ${f.rfc_message_id}` : null,
  f.rfc_message_id ? `References: ${f.rfc_message_id}` : null,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset=UTF-8',
  'Content-Transfer-Encoding: base64',
].filter(Boolean);
const raw = headers.join('\r\n') + '\r\n\r\n' + b64(text);
return [{ json: {
  tenant_id: tenant.tenant_id,
  conversation_id: answer.conversation_id,
  to: f.from_email,
  subject,
  text,
  thread_id: f.gmail_thread_id,
  raw_message: Buffer.from(raw).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
} }];

// Gmail answers { id, threadId } when it sent the email, or { error } when
// it didn't (connection expired, quota...).
const r = $input.first().json;
const status = Number(r.statusCode || 0);
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* not JSON */ } }
const apiError = body && typeof body === 'object' ? body.error : null;
const ok = status >= 200 && status < 300 && !apiError && !!(body && body.id);
const sent = $('Build Reply Email').first().json;
let error = null;
if (!ok) {
  error = apiError
    ? `${apiError.message || 'Gmail refused the email'}${apiError.code ? ` (code ${apiError.code})` : ''}`
    : `Gmail answered with HTTP ${status || 'no response'}`;
}
return [{ json: { ok, error, status, tenant_id: sent.tenant_id, conversation_id: sent.conversation_id, to: sent.to, gmail_id: (body && body.id) || null } }];

// Which files are kept, and which Elliot reads (Claude opens PDFs and
// JPEG/PNG/GIF/WebP photos; the rest are kept for the team).
const MAX_FILES = 10;            // per email
const MAX_BYTES = 25 * 1024 * 1024;
const READ_MAX = 5;              // files Elliot reads per email
const isImage = (t) => /^image\//i.test(t);
const readableType = (t) => /^image\/(jpeg|png|gif|webp)$/i.test(t) || /^application\/pdf$/i.test(t);
const readLimit = (t) => (/pdf/i.test(t) ? 10 : 5) * 1024 * 1024;
// Logos and icons in email signatures arrive as small images: not kept.
const isSignatureImage = (t, size, inline) => isImage(t) && size > 0 && (size < 15000 || (inline && size < 100000));
const safeName = (n) => String(n || 'file').normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9._-]+/g, '_').replace(/^_+|_+$/g, '').slice(-120) || 'file';
function plan(list, ctx) {
  const base = String(ctx.base || '').replace(/\/+$/, '');
  let reading = 0;
  const kept = list.filter((f) => f.size <= MAX_BYTES && !isSignatureImage(f.content_type, f.size, f.inline)).slice(0, MAX_FILES);
  return kept.map((f, i) => {
    const readable = readableType(f.content_type) && f.size > 0 && f.size <= readLimit(f.content_type) && reading < READ_MAX;
    if (readable) reading += 1;
    const path = `${ctx.tenant_id}/${ctx.conversation_id}/${ctx.stamp}-${i + 1}-${safeName(f.filename)}`;
    return { ...f, tenant_id: ctx.tenant_id, conversation_id: ctx.conversation_id, email_message_id: ctx.email_message_id || null,
      path, readable, upload_url: `${base}/storage/v1/object/email-attachments/${path}`, sign_url: `${base}/storage/v1/object/sign/email-attachments/${path}` };
  });
}

// Gmail Trigger (Download Attachments on) puts each file in binary attachment_0, _1...
// Read from the email being handled now (output 1 of the loop is the current
// email; the Gmail Trigger's own first() would always be the first email).
const base = $('Storage Address').first().json.supabase_url;
const f = $('Extract Email Fields').first().json;
const ctx = { base, tenant_id: $('Lookup Tenant by Mailbox').first().json.tenant_id, conversation_id: $('Get or Create Conversation (Email)').first().json.id,
  email_message_id: f.rfc_message_id, stamp: Date.now() };
let bin = {};
try { bin = $('One Email at a Time').first(1).binary || {}; } catch (e) { bin = {}; }
const toBytes = (s) => {
  const m = String(s || '').trim().match(/^([\d.,]+)\s*(B|kB|KB|MB|GB)?$/i);
  if (!m) return Number(s) || 0;
  const n = Number(m[1].replace(',', '.'));
  return Math.round(n * ({ b: 1, kb: 1024, mb: 1048576, gb: 1073741824 }[(m[2] || 'b').toLowerCase()]));
};
const keys = Object.keys(bin).filter((k) => /^attachment_\d+$/.test(k)).sort((a, b) => Number(a.split('_')[1]) - Number(b.split('_')[1]));
const list = keys.map((k) => ({ key: k, filename: bin[k].fileName || k, content_type: String(bin[k].mimeType || 'application/octet-stream').toLowerCase(),
  size: toBytes(bin[k].fileSize), inline: false }));
if (!list.length) return [{ json: { none: true } }];
if (!base) return [{ json: { none: true, not_saved: list.map((x) => x.filename), reason: 'platform_settings.supabase_url is not set' } }];
const files = plan(list, ctx);
if (!files.length) return [{ json: { none: true } }];
return files.map((x) => ({ json: x, binary: { file: bin[x.key] } }));

// One summary for Elliot: every file kept, with a short-lived link for the
// ones Elliot reads (PDFs and photos). Runs on both branches.
const metas = $('Attachment Files').all().map((i) => i.json);
const first = metas[0] || {};
if (first.none) {
  return [{ json: { files: (first.not_saved || []).map((name) => ({ filename: name, saved: false, url: null })) } }];
}
const safeAll = (n) => { try { return $(n).all().map((i) => i.json); } catch (e) { return []; } };
const uploads = safeAll('Upload Attachment');
const signs = $input.all().map((i) => i.json);
const base = String($('Storage Address').first().json.supabase_url || '').replace(/\/+$/, '');
const ok = (r) => r && Number(r.statusCode) >= 200 && Number(r.statusCode) < 300;
const files = metas.map((m, i) => {
  const saved = ok(uploads[i]);
  let s = signs[i] && signs[i].body;
  if (typeof s === 'string') { try { s = JSON.parse(s); } catch (e) { s = null; } }
  const signed = saved && ok(signs[i]) && s && (s.signedURL || s.signedUrl);
  return { filename: m.filename, content_type: m.content_type, size: m.size, saved,
    url: m.readable && signed ? `${base}/storage/v1${signed}` : null };
});
return [{ json: { files } }];
